/**
 * Geometry helpers for spatial-rotation questions. Options are generated by transforming
 * the base shape, so correctness is guaranteed by construction (and checked in tests).
 */
export type Cell = [number, number];

export function normalize(cells: Cell[]): Cell[] {
  const minX = Math.min(...cells.map(([x]) => x));
  const minY = Math.min(...cells.map(([, y]) => y));
  return cells
    .map(([x, y]) => [x - minX, y - minY] as Cell)
    .sort((a, b) => a[1] - b[1] || a[0] - b[0]);
}

/** Rotates 90° clockwise `times` times. */
export function rotate(cells: Cell[], times: number): Cell[] {
  let out = cells;
  for (let i = 0; i < ((times % 4) + 4) % 4; i++) out = out.map(([x, y]) => [-y, x] as Cell);
  return normalize(out);
}

export function mirror(cells: Cell[]): Cell[] {
  return normalize(cells.map(([x, y]) => [-x, y] as Cell));
}

export function sameShape(a: Cell[], b: Cell[]): boolean {
  const na = normalize(a);
  const nb = normalize(b);
  return na.length === nb.length && na.every(([x, y], i) => x === nb[i][0] && y === nb[i][1]);
}

/** True if `candidate` equals `base` under some rotation (mirroring not allowed). */
export function isRotationOf(base: Cell[], candidate: Cell[]): boolean {
  return [0, 1, 2, 3].some((t) => sameShape(rotate(base, t), candidate));
}

/** A shape is chiral when its mirror image cannot be obtained by rotation. */
export function isChiral(cells: Cell[]): boolean {
  return !isRotationOf(cells, mirror(cells));
}
